using CommerceRunTimeDataModel = Microsoft.Dynamics.Commerce.Runtime.DataModel;
using CrtSalesTransaction = Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesTransaction;
using System.Collections.Generic;
using System.Reflection;

[ExtensionOf(classStr(RetailPricingEngineHelper))]
public final class RetailPricingEngineHelperGlobalUnifiedPricing_Extension
{

}

Method.Source:
public static Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesLine getCrtRetailSalesLine(
    SalesPurchLine _salesLine,
    RetailSalesPurchLineMap _retailSalesLine,
    SalesUnit _defaultSalesUnit,
    SalesPurchTable _salesTable)
{
    Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesLine crtSalesLine = next getCrtRetailSalesLine(_salesLine, _retailSalesLine, _defaultSalesUnit, _salesTable);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        SalesPurchLineInterface salesPurchLineInterface = _salesLine.salesPurchLineInterface();
        crtSalesLine.InventoryDimensionId = salesPurchLineInterface.parmInventDimId();
        SalesLine localSalesLine = _salesLine;
        SalesParameters salesParameters = SalesParameters::find();
        switch (salesParameters.PriceDateType)
        {
            case SalesPriceDateType::ShippingDateRequested :
                SalesShippingDateRequested shippingDate = localSalesLine.ShippingDateRequested;
                crtSalesLine.SalesDate = System.DateTimeOffset::Parse(DateTimeUtil::toStr(shippingDate));
                break;
            case SalesPriceDateType::ReceiptDateRequested :
                SalesReceiptDateRequested receiptDate = localSalesLine.ReceiptDateRequested;
                crtSalesLine.SalesDate = System.DateTimeOffset::Parse(DateTimeUtil::toStr(receiptDate));
                break;
            default :
                crtSalesLine.SalesDate = System.DateTimeOffset::UtcNow;
                break;
        }

        if (_salesLine.TableId == tableNum(SalesLine))
        {
            SalesLine salesLineLocal = _salesLine;

            // to do: what if tax inclusive scenario
            crtSalesLine.NetAmount = salesLineLocal.LineAmount;
        }
    }

    return crtSalesLine;
}

protected static boolean shouldSkipCreateCRTRetailSalesLine(
    RetailSalesPurchTableMap _retailSalesTable,
    boolean _isNewLineInterCompanyBuffer,
    InventTransId _interCompanyBufferInventTransId,
    SalesPurchLine _salesPurchLine)
{
    boolean ret = next shouldSkipCreateCRTRetailSalesLine(_retailSalesTable, _isNewLineInterCompanyBuffer, _interCompanyBufferInventTransId, _salesPurchLine);

    if (!ret 
        && FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance())
        && _salesPurchLine.TableId == tableNum(SalesLine))
    {
        SalesLine salesLineLocal = _salesPurchLine as SalesLine;
        if (salesLineLocal.IsFreeItemLine)
        {
            ret = true;
        }
    }

    return ret;
}
